"""Legal & trust pages."""
from kit import page, article, UPDATED, PARTNER_URL

L = [("Privacy Policy", "@@/privacy/"), ("Terms of Use", "@@/terms/"), ("Cookie Policy", "@@/cookies/"), ("Disclaimer", "@@/disclaimer/"), ("Trademark & Copyright", "@@/trademark-disclosure/"), ("Editorial Policy", "@@/editorial-policy/"), ("Accessibility", "@@/accessibility/")]
CONTACT = '<a href="@@/contact/">contact form</a>'


def P(slug, title, desc, body):
    crumbs = [(title, "")]
    page(f"{slug}/", title, desc, article(title, f"Effective {UPDATED}.", crumbs, body, L, title), crumbs, noslide=True)


def build():
    P("privacy", "Privacy Policy", "How High.School collects, uses and protects information, including cookies, Google AdSense advertising, form submissions, and your privacy rights.", f'''
<p>This Privacy Policy explains how High.School (“we”, “us”) handles information when you use high.school and related pages (the “Site”). We keep collection minimal: most tools run entirely in your browser and store data only on your device.</p>
<h2>1. Who the Site is for</h2><p>The Site is intended for users aged <strong>13 and older</strong>, parents and guardians, adult learners and educators. We do not knowingly collect personal information from children under 13. Our forms block submissions from users who identify as under 13. If you believe a child under 13 has provided us information, please use our {CONTACT} and we will delete it.</p>
<h2>2. Information we collect</h2><ul><li><strong>Information you submit</strong> through forms (for example name, email, optional phone, role, grade, goals, location, messages, applications and pledges).</li><li><strong>Tool data</strong> (GPA courses, flashcards, checklists, trackers) is stored in your browser’s local storage on your device and is <em>not</em> sent to us.</li><li><strong>Automatically collected information</strong> by our advertising and hosting providers, such as IP address, device and browser type, pages viewed and cookie identifiers.</li></ul>
<h2>3. How we use information</h2><ul><li>To respond to your requests and provide matched resources you ask for.</li><li>With your consent, to introduce you to a relevant partner (for example a tutoring, test-prep, counseling or online-school provider) for the needs you selected.</li><li>To send newsletters or alerts you sign up for (unsubscribe any time).</li><li>To operate, secure and improve the Site, and to show advertising.</li></ul>
<h2>4. Minors (13–17)</h2><p>For students under 18, our lead forms require confirmation that a parent or guardian approved the request, and we include the parent/guardian in follow-up where possible. <strong>We do not sell personal information, and we do not share a minor’s information with partners without parent/guardian approval.</strong></p>
<h2>5. Advertising and Google AdSense</h2><p>We use Google AdSense to display ads. Third-party vendors, including Google, use cookies to serve ads based on a user’s prior visits to this Site or other websites. Google’s use of advertising cookies enables it and its partners to serve ads based on visits to this Site and/or other sites on the internet. You may opt out of personalized advertising by visiting <a href="https://adssettings.google.com/" target="_blank" rel="noopener">Google Ads Settings</a>, and you can opt out of some third-party vendors’ use of cookies for personalized advertising at <a href="https://www.aboutads.info/choices/" target="_blank" rel="noopener">www.aboutads.info</a>. Learn more about <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noopener">how Google uses information from sites that use its services</a>. Choosing “Non-personalized only” in our cookie notice requests non-personalized ads. Users in the EEA, UK and Switzerland may be shown a consent message from a Google-certified consent management platform.</p>
<h2>6. Service providers</h2><ul><li><strong>Hosting:</strong> GitHub Pages (GitHub, Inc.) serves the Site and may log technical request data.</li><li><strong>Form delivery:</strong> FormSubmit relays form submissions to our inbox.</li><li><strong>Fonts:</strong> Google Fonts.</li><li><strong>Videos:</strong> YouTube (privacy-enhanced mode); YouTube receives data only when you choose to play a video.</li><li><strong>Payments:</strong> if you donate, the payment provider you choose (e.g., PayPal, Stripe, Buy Me a Coffee) processes your payment under its own privacy policy. We never receive full card details.</li></ul>
<h2>7. Sharing</h2><p>We share information only with the service providers above, with partners you ask to be matched with, when required by law, or to protect rights and safety. We do not sell personal information.</p>
<h2>8. Retention</h2><p>We keep form submissions only as long as needed to respond and for reasonable record-keeping, then delete them. Data in your browser stays until you clear it.</p>
<h2>9. Your rights</h2><p>Depending on where you live (for example under the GDPR, UK GDPR, or US state laws such as the CCPA/CPRA), you may have rights to access, correct, delete or object to processing of your personal information, and to opt out of “sale” or “sharing” for targeted advertising. To make a request, use our {CONTACT} and choose “Privacy request.” We will not discriminate against you for exercising your rights.</p>
<h2>10. Security</h2><p>The Site is served over HTTPS. No method of transmission is 100% secure, so please don’t submit sensitive information (such as ID or financial numbers) through our forms.</p>
<h2>11. International users</h2><p>Our providers may process information in the United States and other countries.</p>
<h2>12. Changes</h2><p>We may update this policy and will revise the effective date above.</p>
<h2>13. Contact</h2><p>Questions? Use our {CONTACT}.</p>''')

    P("terms", "Terms of Use", "The terms that govern use of the High.School website, tools, content, forms, contests and partner introductions.", f'''
<p>By using High.School (the “Site”), you agree to these Terms. If you don’t agree, please don’t use the Site.</p>
<h2>1. Eligibility</h2><p>You must be at least 13 years old to use interactive features and forms. Users under 18 should use the Site with a parent or guardian’s awareness.</p>
<h2>2. Educational information only</h2><p>Content is for general educational purposes and is not professional, legal, financial, medical or admissions advice. Requirements, dates and policies change; always confirm with your school, district, college or the official testing organization. See our <a href="@@/disclaimer/">Disclaimer</a>.</p>
<h2>3. Tools</h2><p>Calculators and trackers provide estimates. Your school’s official records and policies prevail. Tool data is stored on your device; you are responsible for backing it up.</p>
<h2>4. Acceptable use</h2><p>Don’t misuse the Site: no unlawful activity, spam, scraping that burdens our servers, attempts to breach security, or submitting false information about yourself or others. Don’t use the Site to commit academic dishonesty.</p>
<h2>5. Intellectual property</h2><p>Site text, design and code are owned by High.School or its licensors. You may share links and use content for personal, non-commercial study and classroom use with attribution. Third-party trademarks belong to their owners (see <a href="@@/trademark-disclosure/">Trademark & Copyright</a>). Embedded videos remain the property of their creators.</p>
<h2>6. User submissions</h2><p>When you submit content (for example contest entries or guide contributions), you confirm it is your own and grant us the license described in the applicable rules or agreement.</p>
<h2>7. Partner introductions</h2><p>If you ask to be matched, any agreement you make with a partner is solely between you and that partner. We vet partners but don’t guarantee their services or results.</p>
<h2>8. Third-party links and ads</h2><p>We aren’t responsible for third-party websites, ads or services.</p>
<h2>9. Contests</h2><p>Contests are governed by the <a href="@@/contests/official-rules/">Official Rules</a>.</p>
<h2>10. Disclaimers and limitation of liability</h2><p>The Site is provided “as is” without warranties of any kind. To the fullest extent permitted by law, High.School is not liable for indirect, incidental or consequential damages arising from use of the Site.</p>
<h2>11. Changes</h2><p>We may update these Terms; continued use means you accept the updated Terms.</p>
<h2>12. Contact</h2><p>Questions? Use our {CONTACT}. Business inquiries: <a href="{PARTNER_URL}" target="_blank" rel="noopener">web.works/contact</a>.</p>''')

    P("cookies", "Cookie Policy", "How High.School uses cookies and local storage, including Google AdSense advertising cookies, and how to control them.", '''
<p>Cookies are small text files stored by your browser. We also use <strong>local storage</strong>, a similar browser feature, to save your tool data and preferences on your device.</p>
<h2>What we use</h2><table><thead><tr><th>Type</th><th>Purpose</th><th>Set by</th></tr></thead><tbody>
<tr><td>Essential local storage</td><td>Remembers your theme, cookie choice, and tool data (GPA courses, flashcards, checklists)</td><td>High.School (stays on your device)</td></tr>
<tr><td>Advertising cookies</td><td>Serve and measure ads, limit repetition, and (if allowed) personalize ads</td><td>Google and its partners via AdSense</td></tr>
<tr><td>Video cookies</td><td>Only set when you click to play a YouTube video</td><td>YouTube (privacy-enhanced mode)</td></tr>
<tr><td>Fonts</td><td>Deliver web fonts</td><td>Google Fonts</td></tr></tbody></table>
<h2>Your choices</h2><ul><li>Use our cookie notice to choose <strong>Accept all</strong> or <strong>Non-personalized only</strong>. To reset your choice, clear this site’s data in your browser.</li><li>Manage personalized Google ads at <a href="https://adssettings.google.com/" target="_blank" rel="noopener">Google Ads Settings</a> and other vendors at <a href="https://www.aboutads.info/choices/" target="_blank" rel="noopener">aboutads.info</a>.</li><li>Block or delete cookies in your browser settings (some features may stop working).</li></ul>
<p>See our <a href="@@/privacy/">Privacy Policy</a> for more.</p>''')

    P("disclaimer", "Disclaimer", "High.School provides general educational information — not professional, legal, financial, medical or admissions advice. Read our full disclaimer.", '''
<h2>Educational information only</h2><p>High.School publishes general educational information to help students, families and educators. It is not professional advice — including academic, admissions, legal, financial, tax or medical advice — and does not create any advisor relationship.</p>
<h2>Accuracy</h2><p>We work hard to keep content accurate and current (see our <a href="@@/editorial-policy/">Editorial Policy</a>), but requirements, test formats, deadlines, fees and policies change. Always confirm with your school, district, state education department, college, or the official testing organization.</p>
<h2>Tools and estimates</h2><p>Calculators provide estimates for planning only. Official GPAs, credits, scores and aid amounts come from your school, testing organization or college.</p>
<h2>No affiliation</h2><p>High.School is independent and not affiliated with or endorsed by any school, district, testing organization or government agency.</p>
<h2>Advertising and referrals</h2><p>The Site displays ads and may earn referral fees from partners when you request an introduction. This does not affect our editorial content.</p>
<h2>External links</h2><p>Links to third-party sites are provided for convenience; we are not responsible for their content.</p>
<h2>Wellbeing content</h2><p>Wellbeing guides are general information. If you or someone you know is in crisis in the US, call or text 988. Elsewhere, contact local emergency services.</p>''')

    P("trademark-disclosure", "Trademark & Copyright Disclosure", "High.School’s trademark and copyright disclosure: descriptive use of “high school”, third-party trademarks (SAT, AP, ACT, IB, National Merit), embedded videos and content ownership.", f'''
<h2>Descriptive use of “high school”</h2><p>“High school” is a generic, descriptive term for secondary education. High.School uses it in its ordinary descriptive sense to describe the subject matter of this website. <strong>We claim no exclusive rights in the generic words “high school,”</strong> and our use is not intended to suggest any affiliation with, or endorsement by, any school, school district, school board, education authority, or any organization that uses “High School” or similar words in its name or marks.</p>
<h2>No affiliation</h2><p>High.School is an independent educational resource. It is not a school, does not grant diplomas or credits, and is not affiliated with, sponsored by or endorsed by any school, district, accrediting body, government agency or testing organization.</p>
<h2>Third-party trademarks</h2><ul><li>SAT®, AP®, Advanced Placement®, PSAT/NMSQT®, CSS Profile™ and Bluebook™ are trademarks registered by or belonging to the College Board.</li><li>ACT® is a registered trademark of ACT Education Corp.</li><li>IB, International Baccalaureate and related marks are trademarks of the International Baccalaureate Organization.</li><li>National Merit® is a registered trademark of National Merit Scholarship Corporation.</li><li>Common App® is a registered trademark of The Common Application, Inc.</li><li>FAFSA® is a registered trademark of the U.S. Department of Education.</li><li>GED® is a registered trademark of the American Council on Education; HiSET® is a registered trademark of its owner.</li><li>YouTube is a trademark of Google LLC. CrashCourse, Khan Academy, TED-Ed, 3Blue1Brown, College Essay Guy and other channel names belong to their respective owners.</li><li>Pomodoro Technique® is a registered trademark of Francesco Cirillo.</li></ul>
<p>These marks are used only to identify the tests, programs and services we write about (nominative use). None of these owners sponsor, endorse or are affiliated with High.School.</p>
<h2>Embedded videos</h2><p>Videos are embedded using YouTube’s official embedded player, as permitted by YouTube’s Terms of Service. All rights in the videos remain with their creators. We do not host, download or modify these videos. Rights holders may request removal of any embed via our {CONTACT}.</p>
<h2>Our content</h2><p>Unless otherwise noted, original text, quizzes, tools, code and design on High.School are © High.School. Practice questions are original and written by our team. Brief quotations, if any, are used for commentary and education.</p>
<h2>Copyright concerns</h2><p>If you believe content on the Site infringes your copyright, send a notice through our {CONTACT} including: identification of the work, the URL of the material, your contact information, a statement of good-faith belief, and a statement that your notice is accurate and that you are the owner or authorized to act. We respond promptly to valid notices.</p>
<h2>Domain inquiries</h2><p>For inquiries about the High.School domain name or website, visit <a href="{PARTNER_URL}" target="_blank" rel="noopener">web.works/contact</a>.</p>''')

    P("editorial-policy", "Editorial Policy", "How High.School researches, writes, reviews, updates and corrects its content, and how advertising and partnerships are kept separate from editorial decisions.", '''
<h2>Our standards</h2><ul><li><strong>Useful first:</strong> every page should answer a real question a student, parent or educator has.</li><li><strong>Accurate:</strong> facts about tests, aid and requirements are checked against official sources (College Board, ACT, IBO, NMSC, StudentAid.gov, NCES, BLS, state education departments).</li><li><strong>Plain English:</strong> we explain jargon and avoid hype.</li><li><strong>Original:</strong> our guides and practice questions are written by our team, not copied.</li></ul>
<h2>How content is made</h2><ol><li>Research from official and reputable sources.</li><li>Drafting by the High.School Editorial Team.</li><li>Review by an editor and, for subject content, a subject-matter reviewer.</li><li>Publication with an “Updated” date.</li><li>Scheduled reviews (at least yearly, and whenever a test or policy changes).</li></ol>
<h2>Use of AI</h2><p>We may use AI-assisted tools for research support, drafting and editing. Every page is reviewed and edited by people, and facts are verified against sources before publishing.</p>
<h2>Advertising & partnerships</h2><p>Ads are served automatically by Google AdSense; we don’t write content to please advertisers. Partners and sponsors never pay for editorial coverage or rankings. Sponsored content, if any, is clearly labeled.</p>
<h2>Corrections</h2><p>Spotted an error? Use our <a href="@@/contact/">contact form</a> and choose “Feedback or correction.” We review every report and update pages promptly.</p>''')

    P("accessibility", "Accessibility Statement", "High.School’s commitment to accessibility: WCAG 2.1 AA goals, keyboard navigation, screen-reader support, dark mode and how to report barriers.", '''
<p>We want High.School to be usable by everyone. Our goal is to meet the <strong>Web Content Accessibility Guidelines (WCAG) 2.1 Level AA</strong>.</p>
<h2>What we do</h2><ul><li>Semantic HTML with headings, landmarks and a “skip to content” link.</li><li>Full keyboard navigation with visible focus indicators.</li><li>Labels for every form field and live regions for results and form status.</li><li>Color contrast checked in light and dark modes; a dark mode toggle in the header.</li><li>Respect for “reduced motion” system settings.</li><li>Videos load only when you choose to play them.</li></ul>
<h2>Known limitations</h2><p>Embedded third-party videos and ads may not fully meet our standards. Video captions are provided by their creators on YouTube.</p>
<h2>Feedback</h2><p>If you find a barrier, please tell us through our <a href="@@/contact/">contact form</a>. We aim to respond within five business days.</p>''')
